9	
10	    init(
11	        isEnabled: Bool,
12	        isObscured: Bool,
13	        @ViewBuilder content: () -> Content,
14	        @ViewBuilder placeholder: () -> Placeholder
15	    ) {
16	        self.isEnabled = isEnabled
17	        self.isObscured = isObscured
18	        self.content = content()
19	        self.placeholder = placeholder()
20	    }
21	
22	    func makeUIViewController(context: Context) -> CaptureProtectedHostingController<Content, Placeholder> {
