52	final class CaptureProtectedHostingController<Content: View, Placeholder: View>: UIViewController {
53	    private let protectedContainer = CaptureProtectedContainerView()
54	    private let contentHost: UIHostingController<Content>
55	    private let placeholderHost: UIHostingController<Placeholder>
56	
57	    init(content: Content, placeholder: Placeholder, isEnabled: Bool, isObscured: Bool) {
58	        self.contentHost = UIHostingController(rootView: content)
59	        self.placeholderHost = UIHostingController(rootView: placeholder)
60	        super.init(nibName: nil, bundle: nil)
61	        protectedContainer.isProtectionEnabled = isEnabled
62	        protectedContainer.isObscured = isObscured
63	    }
64	
65	    @available(*, unavailable)
66	    required init?(coder: NSCoder) {
67	        fatalError("init(coder:) has not been implemented")
68	    }
69	
70	    override func loadView() {
71	        view = protectedContainer
72	    }
73	
74	    override func viewDidLoad() {
75	        super.viewDidLoad()
76	        setupHost(contentHost)
77	        setupHost(placeholderHost)
78	        protectedContainer.setContentView(contentHost.view)
79	        protectedContainer.setPlaceholderView(placeholderHost.view)
80	    }
81	
82	    func update(content: Content, placeholder: Placeholder, isEnabled: Bool, isObscured: Bool) {
83	        contentHost.rootView = content
84	        placeholderHost.rootView = placeholder
85	        protectedContainer.isProtectionEnabled = isEnabled
86	        protectedContainer.isObscured = isObscured
87	    }
88	
89	    func sizeThatFits(_ proposal: ProposedViewSize) -> CGSize {
90	        let width = proposal.width ?? UIView.layoutFittingCompressedSize.width
91	        let height = proposal.height ?? UIView.layoutFittingCompressedSize.height
92	        let fittingSize = CGSize(width: width, height: height)
93	        return contentHost.sizeThatFits(in: fittingSize)
94	    }
95	
96	    private func setupHost<HostedContent: View>(_ host: UIHostingController<HostedContent>) {
97	        addChild(host)
98	        host.view.backgroundColor = .clear
99	        host.view.isUserInteractionEnabled = false
100	        host.didMove(toParent: self)
101	    }
102	}
