104	final class CaptureProtectedContainerView: UIView {
105	    var isProtectionEnabled = false {
106	        didSet { updateProtectionState() }
107	    }
108	
109	    var isObscured = false {
110	        didSet { updateProtectionState() }
111	    }
112	
113	    private let placeholderContainer = UIView()
114	    private let publicContainer = UIView()
115	    private let secureCanvas: UIView?
116	    private let secureTextField = UITextField()
117	    private weak var contentView: UIView?
118	    private weak var placeholderView: UIView?
119	
120	    override init(frame: CGRect) {
121	        secureTextField.isSecureTextEntry = true
122	        secureTextField.isUserInteractionEnabled = false
123	        secureCanvas = Self.makeSecureCanvas(from: secureTextField)
124	        super.init(frame: frame)
125	        setupUI()
126	    }
127	
128	    @available(*, unavailable)
129	    required init?(coder: NSCoder) {
130	        fatalError("init(coder:) has not been implemented")
131	    }
132	
133	    func setContentView(_ view: UIView) {
134	        contentView = view
135	        view.isUserInteractionEnabled = false
136	        updateProtectionState()
137	    }
138	
139	    func setPlaceholderView(_ view: UIView) {
140	        placeholderView = view
141	        view.isUserInteractionEnabled = false
142	        install(view, in: placeholderContainer)
143	        updateProtectionState()
144	    }
145	
146	    private func setupUI() {
147	        isUserInteractionEnabled = false
148	        backgroundColor = .clear
149	        clipsToBounds = false
150	
151	        [placeholderContainer, publicContainer].forEach { container in
152	            container.backgroundColor = .clear
153	            container.isUserInteractionEnabled = false
154	            addSubview(container)
155	            pin(container, to: self)
156	        }
157	
158	        if let secureCanvas {
159	            secureCanvas.backgroundColor = .clear
160	            secureCanvas.isUserInteractionEnabled = false
161	            addSubview(secureCanvas)
162	            pin(secureCanvas, to: self)
163	        }
164	    }
165	
166	    private func updateProtectionState() {
167	        guard let contentView else { return }
168	        let hasSecureCanvas = secureCanvas != nil
169	        let shouldUseSecureCanvas = isProtectionEnabled && hasSecureCanvas
170	        let targetContainer = shouldUseSecureCanvas ? secureCanvas : publicContainer
171	
172	        if let targetContainer, contentView.superview !== targetContainer {
173	            install(contentView, in: targetContainer)
174	        }
175	
176	        placeholderContainer.isHidden = !isProtectionEnabled
177	        publicContainer.isHidden = shouldUseSecureCanvas
178	        secureCanvas?.isHidden = !shouldUseSecureCanvas || isObscured
179	
180	        if isObscured {
181	            bringSubviewToFront(placeholderContainer)
182	        } else {
183	            if shouldUseSecureCanvas, let secureCanvas {
184	                bringSubviewToFront(secureCanvas)
185	            } else {
186	                bringSubviewToFront(publicContainer)
187	            }
188	        }
189	    }
190	
191	    private func install(_ child: UIView, in container: UIView) {
192	        if child.superview !== container {
193	            child.removeFromSuperview()
194	            container.addSubview(child)
195	            pin(child, to: container)
196	        }
197	    }
198	
199	    private func pin(_ child: UIView, to parent: UIView) {
200	        child.translatesAutoresizingMaskIntoConstraints = false
201	        NSLayoutConstraint.activate([
202	            child.leadingAnchor.constraint(equalTo: parent.leadingAnchor),
203	            child.trailingAnchor.constraint(equalTo: parent.trailingAnchor),
204	            child.topAnchor.constraint(equalTo: parent.topAnchor),
205	            child.bottomAnchor.constraint(equalTo: parent.bottomAnchor)
206	        ])
207	    }
208	
209	    private static func makeSecureCanvas(from textField: UITextField) -> UIView? {
210	        guard let canvas = textField.subviews.first else { return nil }
211	        canvas.subviews.forEach { $0.removeFromSuperview() }
212	        canvas.isUserInteractionEnabled = false
213	        return canvas
214	    }
215	}
