1448	private func formatDiagnosticsBytes(_ bytes: Int) -> String {
1449	    guard bytes > 0 else { return "0 B" }
1450	    if bytes >= 1024 * 1024 {
1451	        return String(format: "%.1f MB", Double(bytes) / 1024 / 1024)
1452	    }
1453	    if bytes >= 1024 {
1454	        return String(format: "%.1f KB", Double(bytes) / 1024)
1455	    }
1456	    return "\(bytes) B"
1457	}
